using System;using System.IO;using System.Windows.Forms;
namespace ScoreModern {public sealed partial class Editor {
 string pendingDiskFilename;bool diskFunctionSelection;
 string OriginalDiskContext(){string cwd=Directory.GetCurrentDirectory(),root=Path.GetPathRoot(cwd),drive=root.Length>=2&&root[1]==':'?root.Substring(0,1):root;string path=cwd.Length>=2&&cwd[1]==':'?cwd.Substring(2):cwd;return "Dr="+drive+" Path="+path+"    File="+(String.IsNullOrEmpty(current)?"SCORE.MUS":current)+"    ESC=Exit";}
 string DiskFilenamePrompt(string verb){if(verb=="DRV")return "";if(verb=="CD")return "Enter new path to be default directory ->";return verb=="DIR"?"Enter directory mask or press <Enter> ->":"Enter Filename ->";}
 void StartDiskFilename(string verb,bool selected=false){pendingDiskFilename=verb;diskFunctionSelection=selected;string description=verb=="G"?"Load a new file.":verb=="SA"?"Save current file.":verb=="DEL"?"Delete a file.":verb=="GM"?"Append file.":verb=="RE"?"Read in a text file.":"";Message(selected?description:description+(description.Length==0?"":Environment.NewLine)+DiskFilenamePrompt(verb));command.Clear();command.Focus();}
 bool SubmitDiskFilename(string text){if(pendingDiskFilename==null)return SubmitScor4MacroListing(text);string verb=pendingDiskFilename;if(verb=="CD"){pendingDiskFilename=null;diskFunctionSelection=false;if(!String.IsNullOrWhiteSpace(text))Directory.SetCurrentDirectory(Path.GetFullPath(text.Trim()));Message("");command.Clear();UpdateClassic();return true;}if(verb=="DRV"){pendingDiskFilename=null;diskFunctionSelection=false;StartDriveChange();if(!String.IsNullOrWhiteSpace(text))SubmitDriveChange(text);return true;}if(String.IsNullOrWhiteSpace(text)){if(diskFunctionSelection){StartDiskFilename(verb);return true;}if(verb!="DIR"){StartDiskFilename(verb);return true;}}pendingDiskFilename=null;diskFunctionSelection=false;if(verb=="G")StartLetterLoad(text);else if(verb=="SA")StartLetterSave(text);else if(verb=="DEL")StartDiskDelete(text);else if(verb=="RE")ExecuteOriginalCommandFile("RE "+text);else if(verb=="GM")ExecuteMainLetterCommand("GM",text);else if(verb=="DIR")ShowScoreDirectory(text);else if(verb=="TYPE")StartTypeListing(text.Trim());return true;}
 bool DiskFilenameKey(KeyEventArgs key){if(pendingDiskFilename==null)return false;if(key.KeyCode==Keys.Escape){pendingDiskFilename=null;diskFunctionSelection=false;mode=ScreenMode.Main;Message("");command.Clear();UpdateClassic();command.Focus();key.SuppressKeyPress=true;return true;}if(key.Control||key.Alt||key.KeyCode>=Keys.F1&&key.KeyCode<=Keys.F24){key.SuppressKeyPress=true;return true;}return false;}
 bool DiskFileFunction(int key){if(WindowsDiskFunction(key))return true;if(mode!=ScreenMode.Disk||key!=1&&key!=2&&key!=3&&key!=4&&key!=5&&key!=6&&key!=7&&key!=8)return false;if(key==6){StartDriveChange();return true;}if(key==7){StartDiskFilename("CD");return true;}StartDiskFilename(key==1?"G":key==2?"SA":key==3?"GM":key==4?"RE":key==8?"DEL":"DIR");return true;}
 bool DiskFileCommand(string verb,string arguments){if(mode!=ScreenMode.Disk||verb!="G"&&verb!="SA"&&verb!="DIR"&&verb!="CD"&&verb!="GM")return false;if(arguments.Length==0&&NativeDiskDialogChoice.Files&&(verb=="G"||verb=="SA"||verb=="GM"))WindowsDiskFunction(verb=="G"?1:verb=="SA"?2:3);else if(arguments.Length==0)StartDiskFilename(verb);else if(verb=="G")StartLetterLoad(arguments);else if(verb=="SA")StartLetterSave(arguments);else if(verb=="GM")ExecuteMainLetterCommand("GM",arguments);else if(verb=="CD"){Directory.SetCurrentDirectory(Path.GetFullPath(arguments));Message("");UpdateClassic();}else ShowScoreDirectory(arguments);return true;}
}}
